update public.lessons l set enhancements = $ench${"industryStory":"A team wrote a suite of mocked tests against the response shape from an API design document. Every test was green, yet the feature broke in production: the real service wrapped its payload in a `data` envelope the document never mentioned. Nobody had watched the actual traffic. After that, the team’s rule became \"log it before you mock it\" — capture the real request and response first, and build every fixture from what the endpoint genuinely returns.","davidTip":"Keep a throwaway \"recorder\" test around for each area of the app whose only job is to log network traffic. When an endpoint changes, that test shows you the new shape in seconds — far faster than diffing your fixtures against a moving target by hand.","visualAid":{"type":"comparison","title":"Observing versus controlling traffic","headers":["Tool","What it does","When to reach for it"],"rows":[["page.on(‘request’/‘response’)","Passively watch traffic","Discovering what the app calls"],["page.route + route.continue()","Intercept, then pass through","Watching with a Route in hand"],["page.route + route.fulfill()","Intercept and reply yourself","Mocking a response (next lesson)"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 10 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"badGood":{"label":"faithful vs invented fixture","bad":"~~~ts\n// Real endpoint returns { data: { orders: [...] } }, but the fixture invents a flat shape.\nawait page.route('**/api/orders', async (route) => {\n  await route.fulfill({\n    status: 200,\n    contentType: 'application/json',\n    body: JSON.stringify({ orders: [{ id: 1 }] }), // wrong shape — test passes, prod breaks\n  });\n});\n~~~","good":"~~~ts\n// Fixture mirrors an observed real response, envelope and all.\nimport ordersFixture from './fixtures/orders.json';\n\nawait page.route('**/api/orders', async (route) => {\n  await route.fulfill({\n    status: 200,\n    contentType: 'application/json',\n    body: JSON.stringify(ordersFixture), // { data: { orders: [...] } }\n  });\n});\n~~~"},"davidTip":"Delay a fulfilment with `await new Promise(r => setTimeout(r, 2000))` before `route.fulfill` to test loading states — but keep those delays short and few. A suite full of artificial two-second waits is slow for no product reason; you only need enough delay to prove the spinner appears.","miniChallenge":"Add a fourth test that serves deliberately awkward data — a customer name with emoji and a very long product title — and assert the UI does not overflow or crash. This is the edge-case coverage a real backend rarely hands you on demand."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 10 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A team stubbed their SMS provider to avoid paying for a message on every test run — sensible, and their sign-up suite flew. Months later the provider changed the field name in its send-confirmation response. Every stubbed test stayed green because the stub still returned the old shape, but real sign-ups silently stopped sending codes. There was no real test anywhere to catch it. The fix was a single nightly test against the provider’s sandbox that would have gone red the same day the format changed.","visualAid":{"type":"comparison","title":"Stub the fast suite, keep a real thread","headers":["Concern","Fast stubbed suite","Nightly real suite"],"rows":[["Speed","Instant, deterministic","Slower, hits the sandbox"],["Cost","Free — no real calls","Small — test-mode calls"],["Catches app logic bugs","Yes","Yes"],["Catches provider contract changes","No","Yes"]]},"davidTip":"When you stub a third party, match on its exact host, not a wildcard that could swallow your own API. `page.route('https://api.paymentprovider.com/**', ...)` is safe; `page.route('**/api/**', ...)` will quietly intercept your own backend too and hollow out the test."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 10 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"badGood":{"label":"inventing vs patching a response","bad":"~~~ts\n// Hand-builds a whole profile just to flip one flag — every other field is a guess.\nawait page.route('**/api/profile', async (route) => {\n  await route.fulfill({\n    status: 200,\n    contentType: 'application/json',\n    body: JSON.stringify({ id: 1, name: 'Test', plan: 'enterprise', /* ...guessed fields */ }),\n  });\n});\n~~~","good":"~~~ts\n// Keeps the real response, bends only the field under test.\nawait page.route('**/api/profile', async (route) => {\n  const response = await route.fetch();\n  const json = await response.json();\n  json.plan = 'enterprise';\n  await route.fulfill({ response, json });\n});\n~~~"},"davidTip":"Blocking images and fonts with `route.abort` can shave real time off a large suite that does not assert on them. Do it in a shared fixture rather than per test, and only where the visuals genuinely do not matter to what you are checking.","miniChallenge":"Take a test that currently uses a full invented fixture and rewrite it to fetch the real response and patch only the one field it actually cares about. Note how many fewer assumptions the test now bakes in."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 10 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"A team was proud of a fast, fully mocked suite that stayed green through every release — until a release where it stayed green and the app was broken for every user. An upstream service had changed its response shape; every mock still returned the old one. The suite had quietly become a test of the team’s year-old assumptions rather than of the live system. They kept the fast mocked layer for feedback but added a small nightly end-to-end run against real services, and made the rule explicit: mocked tests prove the code, real tests prove the integration, and only both together prove the product.","visualAid":{"type":"flow","title":"Choosing whether to mock a dependency","steps":[{"label":"Is it your own backend, happy path?","detail":"Prefer real — it is your contract to verify."},{"label":"Is the state hard to trigger for real?","detail":"Mock that specific state, keep a real happy-path test."},{"label":"Is it a flaky or costly third party?","detail":"Stub in the fast suite, keep a nightly real test."},{"label":"Do you need a rare data condition?","detail":"Patch a real response rather than invent a fixture."},{"label":"Whatever you mocked — where is the real coverage?","detail":"If the answer is nowhere, you moved risk, not removed it."}]},"davidTip":"When you present test results, name the layer. \"The mocked suite is green\" and \"the end-to-end suite is green\" are different claims, and blurring them is how teams talk themselves into shipping a fantasy. Say which one you mean."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 10 and l.lesson_number = 5;

